func TestReproLeak(t *testing.T) {
	baseline := liveGoroutines()
	s := &Sender{interval: time.Hour}
	s.RunAsync()
	time.Sleep(50 * time.Millisecond)
	if liveGoroutines() <= baseline { t.Fatal("sender goroutine leaked") }
}
